/* @lc app=leetcode id=2468 lang=kotlin */ class Solution { fun ds(b: Int): Long = (1..b.toString().length).sumOf { d -> (minOf(b.toLong(), Math.pow(10.0, d.toDouble()).toLong() - 1) - Math.pow(10.0, (d - 1).toDouble()).toLong() + 1) * d } fun splitMessage(message: String, limit: Int): Array<String> = message.length.let { L -> (1..L).asSequence().takeWhile { b -> limit - 3 - 2 * b.toString().length >= 1 }.firstOrNull { b -> b.toLong() * (limit - 3 - b.toString().length) - ds(b) >= L }.let { b -> if (b == null) arrayOf<String>() else (1..b).fold(0 to listOf<String>()) { (pos, acc), i -> (limit - 3 - i.toString().length - b.toString().length).let { sz -> (pos + sz) to acc + (message.substring(minOf(pos, L), minOf(L, pos + sz)) + "<$i/$b>") } }.second.toTypedArray() } } }